import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("settle as of date", () => {
  test("settle as of date", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "terms", "5");
    await ui.setSetting(pg_uma, "late-pct", "10.00");
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "100.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    await ui.setToday(pg_uma, "2026-03-05");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    await ui.setToday(pg_uma, "2026-04-20");
    await ui.setSetting(pg_uma, "floor", "5.00");
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle", "2026-04-21")).toBe(false);
    expect(await ui.claimAction(pg_vic, c_ada_1, "settle", "2026-03-01")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle", "2026-03-05")).toBe(true);
    expect(await ui.claimAction(pg_vic, c_ada_1, "settle", "2026-04-20")).toBe(false);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("22.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-due")).toHaveText("2.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("SETTLED");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-log-line")).toHaveText(["DRAFT by uma on 2026-03-01 due=2.00", "OPEN by uma on 2026-03-05 due=4.00", "SETTLED by vic on 2026-04-20 due=2.00"]);
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("20.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("SETTLED");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-log-line")).toHaveText(["DRAFT by uma on 2026-03-01 due=10.00", "OPEN by uma on 2026-03-01 due=10.00", "SETTLED by vic on 2026-04-20 due=20.00"]);
    await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("120.00");
    await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("22.00");
    await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-settled-total")).toHaveText("22.00");
    await expect(pg_vic.getByTestId("rollup-open-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_vic.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-aged-0-30")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-aged-31-60")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("rollup-aged-61")).toHaveText("0.00");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=terms value=5`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=late-pct value=10.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=100.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-01`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=100.00 date=2026-03-01 number=FY2026-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=100.00 due-total=10.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=100.00 due-total=10.00 overdue-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=A rate=20.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=100.00 due-total=20.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=100.00 due-total=20.00 overdue-total=0.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-01 number=FY2026-2`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=120.00 due-total=24.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=120.00 due-total=24.00 overdue-total=0.00`,
      `SNAPSHOT sheet=${sheet} by=uma name=Ada due-total=24.00`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=120.00 due-total=26.40 overdue-total=26.40`,
      `TOTALS sheet=${sheet} by=uma claimed-total=120.00 due-total=26.40 overdue-total=26.40`,
      `SETTING_CHANGED sheet=${sheet} by=uma key=floor value=5.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=20.00 date=2026-03-01 number=FY2026-2 due=2.00 on=2026-03-01`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=120.00 due-total=24.00 overdue-total=22.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=120.00 due-total=24.00 overdue-total=22.00`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=100.00 date=2026-03-01 number=FY2026-1 due=20.00 on=2026-03-05`,
      `ROLLUP sheet=${sheet} by=vic person=Ada claimed=120.00 due-total=22.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=vic claimed-total=120.00 due-total=22.00 overdue-total=0.00`
    ]);
  });
  test("settle as of date scenario 1", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
  test("settle as of date scenario 3", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-04-05");
    expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
    await ui.setSetting(pg_uma, "floor", "2.00");
    await ui.setSetting(pg_uma, "terms", "30");
    await ui.setSetting(pg_uma, "late-pct", "5.00");
    await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
    await ui.setSetting(pg_uma, "terms-A", "20");
    await ui.setSetting(pg_uma, "perm-void", "steward");
    expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
    await ui.setSetting(pg_uma, "grace-C", "5");
    expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.04", "note": ""})).toBe(true);
    await ui.setSetting(pg_uma, "pot", "7.77");
