45	import net.officefloor.hq.app.watch.WatchRepository;
46	import org.springframework.stereotype.Service;
47	import org.springframework.transaction.annotation.Transactional;
48	import org.springframework.transaction.support.TransactionSynchronization;
49	import org.springframework.transaction.support.TransactionSynchronizationManager;
50	import tools.jackson.databind.json.JsonMapper;
51	
52	/**
53	 * A sheet's history: after each change, what the sheet holds is kept under the sheet's today, replacing what was kept
54	 * under that day before. The sheet as it stood at the end of a date is then the last kept under a day on or before
55	 * it: every change made while the sheet's today was on or before that date, and none made later.
56	 */
57	@Service
58	public class SheetHistory {
59	
60	    /** The request header naming the date a user's screen shows the sheet as of (an ISO date): while it is sent, every
61	     *  read of the sheet answers as the sheet stood at the end of that date, that date standing in for its today, and
62	     *  every change is refused (see {@link AsOfGuard}). */
63	    public static final String AS_OF_HEADER = "X-As-Of";
64	
65	    private final SheetSnapshotRepository snapshots;
66	    private final SheetRepository sheets;
67	    private final RateChains rates;
68	    private final PersonRepository people;
69	    private final ClaimRepository claims;
70	    private final PeriodRepository periods;
71	    private final StatementRepository statements;
72	    private final PatronRepository patrons;
73	    private final WatchRepository watches;
74	    private final RoleRepository roles;
75	    private final DelegationRepository delegations;
76	    private final HolidayRepository holidays;
77	    private final JsonMapper json;
78	    private final PoolRepository pools;
79	    private final PoolMemberRepository poolMembers;
80	    private final CrewRepository crews;
81	    private final CrewMemberRepository crewMembers;
82	
83	    public SheetHistory(SheetSnapshotRepository snapshots, SheetRepository sheets, RateChains rates,
84	            PersonRepository people, ClaimRepository claims, PeriodRepository periods, StatementRepository statements,
85	            PatronRepository patrons, WatchRepository watches, RoleRepository roles, DelegationRepository delegations,
86	            HolidayRepository holidays, JsonMapper json, PoolRepository pools, PoolMemberRepository poolMembers,
87	            CrewRepository crews, CrewMemberRepository crewMembers) {
88	        this.pools = pools;
89	        this.poolMembers = poolMembers;
90	        this.crews = crews;
91	        this.crewMembers = crewMembers;
92	        this.snapshots = snapshots;
93	        this.sheets = sheets;
94	        this.rates = rates;
95	        this.people = people;
96	        this.claims = claims;
97	        this.periods = periods;
98	        this.statements = statements;
99	        this.patrons = patrons;
100	        this.watches = watches;
101	        this.roles = roles;
102	        this.delegations = delegations;
103	        this.holidays = holidays;
104	        this.json = json;
105	    }
106	
107	    /** Keep what the sheet holds once the change being made is done: just before the current transaction commits,
108	     *  once however many changes it records; outside a transaction, at once. */
109	    public void keepOnCommit(String sheetId) {
110	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
111	            keep(sheetId);
112	            return;
113	        }
114	        String key = SheetHistory.class.getName() + ":" + sheetId;
115	        if (TransactionSynchronizationManager.hasResource(key)) {
116	            return;
117	        }
118	        TransactionSynchronizationManager.bindResource(key, Boolean.TRUE);
119	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
120	            @Override
121	            public void beforeCommit(boolean readOnly) {
122	                if (!readOnly) {
123	                    keep(sheetId);
124	                }
125	            }
126	
127	            @Override
128	            public void afterCompletion(int status) {
129	                TransactionSynchronizationManager.unbindResourceIfPossible(key);
130	            }
131	        });
132	    }
133	
134	    /** Keep what the sheet holds now under its today. */
135	    @Transactional
136	    public void keep(String sheetId) {
137	        Sheet sheet = sheets.findById(sheetId).orElse(null);
138	        if (sheet == null) {
139	            return;
140	        }
141	        List<Rate> sheetRates = rates.ratesOf(sheetId);
142	        List<Person> sheetPeople = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
143	        List<Claim> sheetClaims = claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
144	        Map<String, List<Long>> watched = new TreeMap<>();
145	        watches.findBySheetIdOrderByIdAsc(sheetId).forEach(w ->
146	                watched.computeIfAbsent(w.getUserName(), u -> new ArrayList<>()).add(w.getPersonId()));
147	        SheetState.Views views = new SheetState.Views(
148	                sheetPeople.stream().map(p -> PersonView.of(p, sheet.getToday())).toList(),
149	                sheetClaims.stream().map(ClaimView::of).map(SheetHistory::unlocked).toList(),
150	                viewsOf(sheetRates),
151	                periods.findBySheetIdOrderByFromDateAsc(sheetId).stream().map(PeriodView::of).toList(),
152	                StatementService.summarize(statements.findBySheetIdOrderByIdAsc(sheetId)).stream()
153	                        .map(SummaryView::of).toList(),
154	                patrons.findBySheetIdOrderByIdAsc(sheetId).stream().map(PatronView::of).toList(),
155	                watched,
156	                roles.findBySheetIdOrderByUserName(sheetId).stream().map(RoleView::of).toList(),
157	                delegations.findBySheetIdOrderByIdAsc(sheetId).stream().map(DelegationView::of).toList(),
158	                holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(HolidayView::of).toList());
159	        List<SheetState.AncestorState> ancestors = rates.ancestorsOf(sheetId).stream().map(ancestor -> {
160	            List<Rate> ancestorRates = rates.ratesOf(ancestor);
161	            return new SheetState.AncestorState(ancestor, SheetState.statesOf(ancestorRates), viewsOf(ancestorRates));
162	        }).toList();
163	        SheetState state = SheetState.of(sheet, sheetRates, sheetPeople, sheetClaims, views, ancestors,
164	                poolStates(sheetId), crewStates(sheetId));
165	        snapshots.deleteBySheetIdAndAsOf(sheetId, sheet.getToday());
166	        snapshots.saveAndFlush(new SheetSnapshot(sheetId, sheet.getToday(), json.writeValueAsString(state)));
167	    }
168	
169	    /** The sheet's pools as they stand now, each with its memberships in the order they were added. */
170	    private List<SheetState.PoolState> poolStates(String sheetId) {
171	        List<Pool> sheetPools = pools.findBySheetIdOrderByIdAsc(sheetId);
172	        Map<Long, List<PoolMember>> byPool = poolMembers.findByPoolIdInOrderByIdAsc(
173	                sheetPools.stream().map(Pool::getId).toList()).stream()
174	                .collect(Collectors.groupingBy(PoolMember::getPoolId));
175	        return sheetPools.stream().map(p -> new SheetState.PoolState(p.getId(), p.getName(),
176	                byPool.getOrDefault(p.getId(), List.of()).stream().map(m -> new SheetState.PoolMemberState(
177	                        m.getPersonId(), m.getMemberPoolId(), m.getShare(), m.getFrom(), m.getTo())).toList()))
178	                .toList();
179	    }
180	
181	    /** The sheet's crews as they stand now, each with its members in the order they were added. */
182	    private List<SheetState.CrewState> crewStates(String sheetId) {
183	        List<Crew> sheetCrews = crews.findBySheetIdOrderByIdAsc(sheetId);
184	        Map<Long, List<CrewMember>> byCrew = crewMembers.findByCrewIdInOrderByIdAsc(
185	                sheetCrews.stream().map(Crew::getId).toList()).stream()
186	                .collect(Collectors.groupingBy(CrewMember::getCrewId));
187	        return sheetCrews.stream().map(c -> new SheetState.CrewState(c.getId(), c.getName(), c.getLeadId(),
188	                byCrew.getOrDefault(c.getId(), List.of()).stream().map(CrewMember::getPersonId).toList())).toList();
189	    }
190	
191	    /** The sheet as it stood at the end of a date; empty when no change was made on it by then. */
192	    @Transactional(readOnly = true)
193	    public Optional<SheetState> asOf(String sheetId, LocalDate date) {
194	        return snapshots.findFirstBySheetIdAndAsOfLessThanEqualOrderByAsOfDescIdDesc(sheetId, date)
195	                .map(s -> json.readValue(s.getState(), SheetState.class));
196	    }
197	
198	    /** The line of rates as it stood at the end of a date: the sheet's own then, then each of its ancestors' as
199	     *  they stood then (none for one with no change made on it by then). */
200	    @Transactional(readOnly = true)
201	    public RateChain ratesAsOf(String sheetId, LocalDate date) {
202	        Optional<SheetState> then = asOf(sheetId, date);
203	        return ratesOf(sheetId, then.orElse(null), date);
204	    }
205	
206	    /** The line of rates of the sheet as it stood then (none: no change made on it by then): its own, then each of
207	     *  its ancestors' as they stood when that state was kept; for a state kept before ancestors were recorded, or
208	     *  none, each ancestor's as it stood at the end of the date. */
209	    @Transactional(readOnly = true)
210	    public RateChain ratesOf(String sheetId, SheetState then, LocalDate date) {
211	        List<Rate> own = then == null ? List.of() : then.rebuildRates(sheetId);
212	        if (then != null && then.ancestors() != null) {
213	            return new RateChain(Stream.concat(Stream.of(own),
214	                    then.ancestors().stream().map(SheetState.AncestorState::rebuildRates)).toList());
215	        }
216	        return new RateChain(Stream.concat(Stream.of(own), rates.ancestorsOf(sheetId).stream()
217	                .map(id -> asOf(id, date).map(state -> state.rebuildRates(id)).orElse(List.<Rate>of()))).toList());
218	    }
219	
220	    /** The rates the sheet inherited at the end of a date, nearest ancestor first, as the screen reads them: each
221	     *  ancestor's as it stood when the sheet's state for that date was kept (see {@link #ratesOf}). */
222	    @Transactional(readOnly = true)
223	    public List<List<RateView>> inheritedAsOf(String sheetId, LocalDate date) {
224	        Optional<SheetState> then = asOf(sheetId, date);
225	        if (then.isPresent() && then.get().ancestors() != null) {
226	            return then.get().ancestors().stream().map(SheetState.AncestorState::views).toList();
227	        }
228	        return rates.ancestorsOf(sheetId).stream().map(ancestor -> viewsAsOf(ancestor, date).rates()).toList();
229	    }
230	
231	    /** The rates as the screen reads them: by grade, in the order they take effect. */
232	    private static List<RateView> viewsOf(List<Rate> sheetRates) {
233	        return sheetRates.stream().sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
234	                .map(RateView::of).toList();
235	    }
236	
237	    /** The claim as kept: no one's editor lock is part of what the sheet held. */
238	    private static ClaimView unlocked(ClaimView c) {
239	        return new ClaimView(c.id(), c.personId(), c.amount(), c.date(), c.note(), c.status(), c.number(),
240	                c.settledDue(), c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(),
241	                c.log(), c.proofs(), c.splitFrom(), null, c.lateEntry(), c.remindedOn(), c.ref(), c.tags(),
242	                c.voidReason(), c.comments(), c.editedBy(), c.batch(), c.lines(), c.waived(), c.statedLate(),
243	                c.proofReceipts(), c.proofPhotos(), c.held());
244	    }
245	
246	    /** The lists the screen reads of the sheet as it stood at the end of a date; none when no change was made on it
247	     *  by then. */
248	    @Transactional(readOnly = true)
249	    public SheetState.Views viewsAsOf(String sheetId, LocalDate date) {
250	        return asOf(sheetId, date).map(SheetState::views).orElse(SheetState.Views.NONE);
251	    }
252	
253	    /** The people as the screen read them at the end of a date, each with the grade in force on it. */
254	    @Transactional(readOnly = true)
255	    public List<PersonView> peopleAsOf(String sheetId, LocalDate date) {
256	        return asOf(sheetId, date).map(s -> s.people(sheetId, date)).orElse(List.of());
257	    }
258	
259	    /** The sheet as it stood at the end of a date, unsaved, with that date standing in for its today: as it was
260	     *  started when no change was made on it by then. Its parent, not dated, is the one it names now. */
261	    @Transactional(readOnly = true)
262	    public Sheet sheetAsOf(Sheet live, LocalDate date) {
263	        return asOf(live.getId(), date).map(s -> s.rebuildSheet(live, date))
264	                .orElseGet(() -> {
265	                    Sheet started = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), date);
266	                    started.setParentId(live.getParentId());
267	                    return started;
268	                });
269	    }
270	}
