1	package net.officefloor.hq.app.history;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import java.util.Map;
7	import java.util.Optional;
8	import java.util.TreeMap;
9	import net.officefloor.hq.app.claim.ClaimController.ClaimView;
10	import net.officefloor.hq.app.patron.PatronController.PatronView;
11	import net.officefloor.hq.app.period.PeriodController.PeriodView;
12	import net.officefloor.hq.app.person.PersonController.PersonView;
13	import net.officefloor.hq.app.rate.RateController.RateView;
14	import net.officefloor.hq.app.holiday.HolidayController.HolidayView;
15	import net.officefloor.hq.app.role.DelegationController.DelegationView;
16	import net.officefloor.hq.app.role.RoleController.RoleView;
17	import net.officefloor.hq.app.statement.StatementController.SummaryView;
18	import net.officefloor.hq.app.claim.Claim;
19	import net.officefloor.hq.app.claim.ClaimStatus;
20	import net.officefloor.hq.app.person.GradeFrom;
21	import net.officefloor.hq.app.person.Hold;
22	import net.officefloor.hq.app.person.PastRetirement;
23	import net.officefloor.hq.app.person.Person;
24	import net.officefloor.hq.app.rate.Rate;
25	import net.officefloor.hq.app.rate.RateVersion;
26	import net.officefloor.hq.app.sheet.Sheet;
27	
28	/** What a sheet held at a moment. As far as a person's figures depend on it (its dated settings and policy date, its
29	 *  rates, its people and its claims) each part is rebuilt as an unsaved entity, so the figures of the sheet as it
30	 *  stood then are worked out by the same rules as the live ones. Alongside, the rest of what the screen shows of it,
31	 *  as the screen reads it: its other settings, and each list the screen reads (see {@link Views}). */
32	public record SheetState(List<SettingState> settings, LocalDate policyDate, List<RateState> rates,
33	        List<PersonState> people, List<ClaimState> claims, Map<String, String> permissions,
34	        LocalDate periodNumberingFrom, Integer graceDays, boolean archived, Views views, LocalDate entryDate,
35	        Integer lastSettleBatch, BigDecimal pot, Integer fiscalStartMonth, BigDecimal alertThreshold,
36	        Integer escalateAfter, Integer reviewSla, String proofKinds, List<AncestorState> ancestors,
37	        List<PoolState> pools, List<CrewState> crews, String defaultGrade) {
38	
39	    /** A pool as it stood, with its memberships in the order they were added (pools and crews are null in a state
40	     *  kept before they were recorded). */
41	    public record PoolState(long id, String name, List<PoolMemberState> members) {
42	    }
43	
44	    /** A membership of a pool as it stood: a person's (personId) or another pool's (memberPoolId). */
45	    public record PoolMemberState(Long personId, Long memberPoolId, BigDecimal share, LocalDate from, LocalDate to) {
46	    }
47	
48	    /** A crew as it stood: its lead and its members' person ids, in the order they were added. */
49	    public record CrewState(long id, String name, Long leadId, List<Long> members) {
50	    }
51	
52	    /** An ancestor's rates as they stood when the sheet's state was kept, nearest ancestor first: what the sheet then
53	     *  inherited (none recorded in a state kept before ancestors were). */
54	    public record AncestorState(String sheetId, List<RateState> rates, List<RateView> views) {
55	
56	        /** The ancestor's rates as they stood then, unsaved. */
57	        public List<Rate> rebuildRates() {
58	            return SheetState.rebuildRates(sheetId, rates);
59	        }
60	    }
61	
62	    /** Each list the screen reads of the sheet, as it read it then; a person's grade there is the one in force on the
63	     *  sheet's today then (see {@link #people(LocalDate)} for it on another day). */
64	    public record Views(List<PersonView> people, List<ClaimView> claims, List<RateView> rates,
65	            List<PeriodView> periods, List<SummaryView> statements, List<PatronView> patrons,
66	            Map<String, List<Long>> watches, List<RoleView> roles, List<DelegationView> delegations,
67	            List<HolidayView> holidays) {
68	
69	        /** Nothing: a sheet as it stood before any change was made on it. */
70	        public static final Views NONE = new Views(List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
71	                Map.of(), List.of(), List.of(), List.of());
72	    }
73	
74	    public record SettingState(String key, LocalDate from, String value) {
75	    }
76	
77	    /** A rate as it stood; claimsAfter is set for a forward-only one (null in a state kept before rates could be),
78	     *  with the older versions a claim it does not apply to may take, newest first. */
79	    public record RateState(String grade, LocalDate from, LocalDate to, BigDecimal rate, Long claimsAfter,
80	            List<EarlierRateState> earlier) {
81	
82	        public RateState {
83	            earlier = earlier == null ? List.of() : earlier;
84	        }
85	    }
86	
87	    public record EarlierRateState(int version, BigDecimal rate, LocalDate to, Long claimsAfter) {
88	    }
89	
90	    public record GradeState(LocalDate from, String grade) {
91	    }
92	
93	    public record TermsState(LocalDate from, Integer terms) {
94	    }
95	
96	    public record HoldState(LocalDate from, LocalDate to) {
97	    }
98	
99	    public record RetirementState(LocalDate from, LocalDate to) {
100	    }
101	
102	    public record PersonState(long id, String name, List<GradeState> grades, Integer terms, LocalDate retiredFrom,
103	            List<HoldState> holds, List<RetirementState> pastRetirements, List<TermsState> datedTerms) {
104	
105	        /** The person as they stood then, unsaved. */
106	        public Person rebuild(String sheetId) {
107	            Person person = new Person(sheetId, name, grades.get(0).grade());
108	            grades.stream().skip(1).forEach(g -> person.setGradeFrom(g.from(), g.grade()));
109	            person.setTerms(terms);
110	            if (datedTerms != null) {
111	                datedTerms.forEach(t -> person.setTermsFrom(t.from(), t.terms()));
112	            }
113	            person.setRetiredFrom(retiredFrom);
114	            holds.forEach(h -> person.addHold(new Hold(h.from(), h.to())));
115	            if (pastRetirements != null) {
116	                pastRetirements.forEach(r -> person.addPastRetirement(new PastRetirement(r.from(), r.to())));
117	            }
118	            return person;
119	        }
120	    }
121	
122	    public record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
123	            String corrects, long listed, ClaimStatus status, String number, BigDecimal settledDue, boolean stated,
124	            BigDecimal statedDue, LocalDate deferredUntil, LocalDate remindedOn, String ref, String tags,
125	            boolean waived, BigDecimal statedLate, boolean held) {
126	
127	        /** The claim as it stood then, unsaved. */
128	        public Claim rebuild(String sheetId) {
129	            Claim claim = new Claim(sheetId, personId, amount, date, dueBy, note, corrects, listed);
130	            claim.setStatus(status);
131	            claim.setNumber(number);
132	            claim.setSettledDue(settledDue);
133	            claim.setDeferredUntil(deferredUntil);
134	            claim.remind(remindedOn);
135	            claim.setRef(ref);
136	            claim.setTags(tags);
137	            if (waived) {
138	                claim.waive();
139	            }
140	            claim.setHeld(held);
141	            if (stated) {
142	                claim.bind(statedDue, statedLate);
143	            }
144	            return claim;
145	        }
146	    }
147	
148	    /** What the sheet holds now. */
149	    public static SheetState of(Sheet sheet, List<Rate> rates, List<Person> people, List<Claim> claims, Views views,
150	            List<AncestorState> ancestors, List<PoolState> pools, List<CrewState> crews) {
151	        return new SheetState(
152	                sheet.getSettings().stream().map(s -> new SettingState(s.getKey(), s.getFrom(), s.getValue())).toList(),
153	                sheet.getPolicyDate(),
154	                statesOf(rates),
155	                people.stream().map(SheetState::stateOf).toList(),
156	                claims.stream().map(c -> new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(),
157	                        c.getDueBy(), c.getNote(), c.getCorrects(), c.getListed(), c.getStatus(), c.getNumber(),
158	                        c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getDeferredUntil(), c.getRemindedOn(), c.getRef(), c.getTags(),
159	                        c.isWaived(), c.getBoundLate(), c.isHeld())).toList(),
160	                new TreeMap<>(sheet.getPermissions()), sheet.getPeriodNumberingFrom(), sheet.getGraceDays(),
161	                sheet.isArchived(), views, sheet.getEntryDate(), sheet.getLastSettleBatch(),
162	                sheet.getPot(), sheet.getFiscalStartMonth(), sheet.getAlertThreshold(),
163	                sheet.getEscalateAfter(), sheet.getReviewSla(), sheet.getProofKinds(), ancestors, pools, crews,
164	                sheet.getDefaultGrade());
165	    }
166	
167	    /** The rates as they stand now. */
168	    public static List<RateState> statesOf(List<Rate> rates) {
169	        return rates.stream().map(r -> new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getRate(),
170	                r.getClaimsAfter(), r.getEarlier().stream().map(v -> new EarlierRateState(v.getVersion(),
171	                        v.getRate(), v.getToDate(), v.getClaimsAfter())).toList())).toList();
172	    }
173	
174	    /** The people as the screen read them then, each with the grade in force on {@code today}. */
175	    public List<PersonView> people(String sheetId, LocalDate today) {
176	        return views.people().stream().map(v -> person(v.id())
177	                .map(p -> new PersonView(v.id(), v.name(), p.rebuild(sheetId).gradeOn(today), v.grades(),
178	                        p.rebuild(sheetId).termsOn(today),
179	                        v.version(), v.retired(), v.retiredFrom(), v.held(), v.holds(), v.contact(), v.aliases(), v.clashing(), v.origin(),
180	                        v.pastRetirements(), v.tags(), v.undatedTerms(), v.datedTerms(), v.flag()))
181	                .orElse(v)).toList();
182	    }
183	
184	    private static PersonState stateOf(Person p) {
185	        List<GradeFrom> grades = p.getGrades();
186	        return new PersonState(p.getId(), p.getName(),
187	                grades.stream().map(g -> new GradeState(g.getFromDate(), g.getGrade())).toList(), p.getTerms(),
188	                p.getRetiredFrom(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList(),
189	                p.getPastRetirements().stream().map(r -> new RetirementState(r.getFromDate(), r.getToDate())).toList(),
190	                p.getDatedTerms().stream().map(t -> new TermsState(t.getFromDate(), t.getTerms())).toList());
191	    }
192	
193	    /** The sheet as it stood then, unsaved, with {@code today} standing in for its today. */
194	    public Sheet rebuildSheet(Sheet live, LocalDate today) {
195	        Sheet sheet = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), today);
196	        settings.forEach(s -> sheet.record(s.key(), s.from(), s.value()));
197	        sheet.setPolicyDate(policyDate);
198	        if (permissions != null) {
199	            permissions.forEach(sheet::setPermission);
200	        }
201	        sheet.setPeriodNumberingFrom(periodNumberingFrom);
202	        sheet.setGraceDays(graceDays);
203	        sheet.setEscalateAfter(escalateAfter);
204	        sheet.setReviewSla(reviewSla);
205	        sheet.setEntryDate(entryDate);
206	        sheet.setPot(pot);
207	        sheet.setAlertThreshold(alertThreshold);
208	        sheet.setProofKinds(proofKinds);
209	        sheet.setDefaultGrade(defaultGrade);
210	        sheet.setFiscalStartMonth(fiscalStartMonth == null ? 1 : fiscalStartMonth);
211	        // The parent is not dated: it is the one the sheet names now.
212	        sheet.setParentId(live.getParentId());
213	        if (lastSettleBatch != null) {
214	            sheet.setLastSettleBatch(lastSettleBatch);
215	        }
216	        if (archived) {
217	            sheet.archive();
218	        }
219	        return sheet;
220	    }
221	
222	    /** The rates as they stood then, unsaved. */
223	    public List<Rate> rebuildRates(String sheetId) {
224	        return rebuildRates(sheetId, rates);
225	    }
226	
227	    private static List<Rate> rebuildRates(String sheetId, List<RateState> rates) {
228	        return rates.stream().map(r -> {
229	            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.rate());
230	            rate.setToDate(r.to());
231	            rate.setClaimsAfter(r.claimsAfter());
232	            rate.setEarlier(r.earlier().stream()
233	                    .map(v -> new RateVersion(null, v.version(), v.rate(), v.to(), v.claimsAfter())).toList());
234	            return rate;
235	        }).toList();
236	    }
237	
238	    /** The people as they stood then, unsaved, each with the id they had. */
239	    public List<Person> rebuildPeople(String sheetId) {
240	        return people.stream().map(p -> {
241	            Person person = p.rebuild(sheetId);
242	            person.rebuiltWithId(p.id());
243	            return person;
244	        }).toList();
245	    }
